def seg_cells(a,b):
    # integer cells on segment via sampling
    import math
    cells=set()
    n=max(abs(a[0]-b[0]),abs(a[1]-b[1]))
    if n==0: return {a}
    for i in range(n+1):
        r=round(a[0]+(b[0]-a[0])*i/n); c=round(a[1]+(b[1]-a[1])*i/n)
        cells.add((r,c))
    return cells
